<?php
declare(strict_types=1);

require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/includes/auth.php';
requireVisitor();

$stats = $pdo->query("SELECT COUNT(*) AS total,COALESCE(SUM(status_arsip='Aktif'),0) AS aktif,COALESCE(SUM(status_arsip='Permanen'),0) AS permanen,COALESCE(SUM(status_arsip='Musnah'),0) AS musnah FROM arsip")->fetch();
$types = $pdo->query("SELECT COALESCE(NULLIF(j.nama_jenis, ''), 'Belum dikategorikan') AS nama_jenis,COUNT(*) AS jumlah FROM arsip a LEFT JOIN jenis_surat j ON j.jenis_surat_id=a.jenis_surat_id GROUP BY j.jenis_surat_id,j.nama_jenis ORDER BY jumlah DESC LIMIT 6")->fetchAll();
$typeTotal = array_sum(array_column($types, 'jumlah'));
$typeColors = ['#1459cf', '#20a45a', '#f97316', '#7441bb', '#0f8b9d', '#e53e3e'];
$segments = [];
$start = 0;
foreach ($types as $index => $type) {
    $end = $start + ((int) $type['jumlah'] / max($typeTotal, 1) * 100);
    $segments[] = $typeColors[$index % count($typeColors)] . ' ' . $start . '% ' . $end . '%';
    $types[$index]['color'] = $typeColors[$index % count($typeColors)];
    $types[$index]['percent'] = (int) round((int) $type['jumlah'] / max($typeTotal, 1) * 100);
    $start = $end;
}
$units = $pdo->query('SELECT u.nama_unit,COUNT(a.arsip_id) AS jumlah FROM unit_kerja u LEFT JOIN arsip a ON a.unit_id=u.unit_id GROUP BY u.unit_id,u.nama_unit ORDER BY jumlah DESC LIMIT 7')->fetchAll();
$maxUnit = max(array_column($units, 'jumlah') ?: [1]);
$visitorUsername = trim((string) ($_SESSION['username'] ?? '')) ?: 'Visitor';
?>
<?php $assetBase = rtrim(str_replace('\\', '/', dirname((string) ($_SERVER['SCRIPT_NAME'] ?? ''))), '/'); ?>
