ca dan dicari.</p></div><time><i class="material-symbols-outlined">calendar_month</i><?=e(date('l, d F Y'))?></time></section><section class="visitor-stats"><article><i class="material-symbols-outlined blue">folder</i><small>Total Arsip</small><strong><?=(int)$stats['total']?></strong><span>Dokumen arsip tersedia</span></article><article><i class="material-symbols-outlined green">verified_user</i><small>Arsip Aktif</small><strong><?=(int)$stats['aktif']?></strong><span>Arsip masih aktif</span></article><article><i class="material-symbols-outlined cyan">star</i><small>Arsip Permanen</small><strong><?=(int)$stats['permanen']?></strong><span>Arsip permanen</span></article><article><i class="material-symbols-outlined red">delete</i><small>Sudah Musnah</small><strong><?=(int)$stats['musnah']?></strong><span>Status arsip</span></article></section><section class="visitor-mid"><section class="visitor-card visitor-search"><h2><i class="material-symbols-outlined">search</i>Pencarian Arsip</h2><form method="get" action="visitor-arsip.php"><input name="q" placeholder="Masukkan No. Registrasi / No. Surat / Perihal" required><button>Cari</button></form><small>Cari berdasarkan nomor registrasi, nomor surat, atau perihal.</small></section><section class="visitor-card visitor-summary"><h2><i class="material-symbols-outlined">info</i>Ringkasan Akses</h2><p>Visitor memiliki akses baca dan pencarian arsip.</p><a href="visitor-arsip.php">Buka Pencarian <i class="material-symbols-outlined">arrow_forward</i></a></section></section><section class="visitor-charts"><section class="visitor-card"><h2>Grafik Arsip Berdasarkan Unit</h2><div class="bar-chart"><?php foreach($units as $unit):?><div class="bar-item"><strong><?=(int)$unit['jumlah']?></strong><i style="height:<?=max(4, (int)$unit['jumlah'] * 100 / $maxUnit)?>%"></i><span><?=e($unit['nama_unit'])?></span></div><?php endforeach;?><?php if(!$units):?><p>Belum ada data arsip.</p><?php endif;?></div></section><section class="visitor-card"><h2>Distribusi Jenis Surat</h2><?php if($types):?><div class="donut-layout"><div class="donut" style="background:conic-gradient(<?=e(implode(',', $segments))?>)" aria-label="Distribusi jenis surat"><div><small>Total</small><strong><?=$typeTotal?></strong><span>Arsip</span></div></div><ul class="type-list"><?php foreach($types as $type):?><li title="<?=e($type['nama_jenis'])?>: <?=(int)$type['jumlah']?> arsip, <?=(int)$type['percent']?>%"><i style="background:<?=e($type['color'])?>"></i><span><?=e($type['nama_jenis'])?></span><b><?=(int)$type['jumlah']?> arsip<br><small><?=(int)$type['percent']?>%</small></b></li><?php endforeach;?></ul></div><?php else:?><div class="archive-empty"><i class="material-symbols-outlined">donut_large</i><h3>Belum ada data jenis surat</h3></div><?php endif;?></section></section></main></div></body></html>
